  "install.title": "Instalar {brand}",
  "install.body": "Añádelo al escritorio o a la pantalla de inicio. Así, las herramientas del navegador funcionan sin conexión.",
  "install.button": "Instalar",
  "install.manual": "En el menú del navegador, elige Instalar aplicación o Añadir a pantalla de inicio.",
